def nth_prime(n: int) -> int:
    """Return the n-th prime (1-based: nth_prime(1) == 2)."""
    if n < 1:
        raise ValueError('n must be >= 1')
    # Upper bound: p(n) < n(ln n + ln ln n) for n >= 6
    import math
    if n < 6:
        limit = 15
    else:
        limit = int(n * (math.log(n) + math.log(math.log(n)))) + 10
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, limit + 1, i)))
    count = 0
    for i, is_prime in enumerate(sieve):
        if is_prime:
            count += 1
            if count == n:
                return i
    raise ValueError('bound too small')

# Example:
print(nth_prime(1))    # 2
print(nth_prime(10))   # 29
print(nth_prime(100))  # 541

