// Memoized (top-down) — cache results per n:
const memo = {};
function fibMemo(n) {
    if (n <= 1) return n;
    if (n in memo) return memo[n];
    memo[n] = fibMemo(n - 1) + fibMemo(n - 2);
    return memo[n];
}

