def binary_search(arr: list[int], target: int) -> int:
    """Return the index of target in sorted arr, or -1."""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

# Example:
print(binary_search([1, 3, 5, 7, 9, 11], 7))  # 3

